module committed

struct State {
    counter: u64,
    owner: Address,
}

action reveal(witness expected: Commitment<State>, witness opening: Opening<State>) -> u64 {
    verification
        let state = commitment::open(expected, opening)
        require state.counter > 0
return 0
}

module committed_construct
struct State { counter: u64 }
action verify(witness value: State) -> u64 { verification let left = commitment::commit(value) let right = commitment::commit(value) require left == right return 0 }
